import Foundation
import MongoKitten

/// A document of the "audit-log" collection. A property stays nil until it is set or read.
public struct AuditLog: Sendable, Equatable {
    public var id: String?
    public var at: Date?
    public var by: BsonValue?
    /// As it was read: a change writes only what differs
    var loadedDocument = Loaded()

    public init(id: String? = nil, at: Date? = nil, by: BsonValue? = nil) {
        self.id = id
        self.at = at
        self.by = by
    }
}

extension AuditLog: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> AuditLog {
        var entity = AuditLog(
            id: try Bson.read(document, "_id", Bson.asText),
            at: try Bson.read(document, "at", Bson.asDate),
            by: try Bson.read(document, "by", Bson.asAny))
        entity.loadedDocument = Loaded(document: try entity.toDocument())
        return entity
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "_id", self.id, Bson.ofText)
        try Bson.write(&document, "at", self.at, Bson.ofDate)
        try Bson.write(&document, "by", self.by, Bson.ofAny)
        return document
    }
}

import Foundation
import MongoKitten

/// A document of the "products" collection. A property stays nil until it is set or read.
public struct Product: Sendable, Equatable {
    public var id: String?
    public var sku: String?
    public var price: Decimal?
    public var stock: Double?
    public var weight: Double?
    public var big: Int?
    public var created: Date?
    public var reference: UUID?
    public var picture: Data?
    public var key: UUID?
    public var pattern: BsonValue?
    public var patterns: [BsonValue]?
    public var text: String?
    public var parts: [Product.Part]?
    public var low: Int?
    /// As it was read: a change writes only what differs
    var loadedDocument = Loaded()

    public init(id: String? = nil, sku: String? = nil, price: Decimal? = nil, stock: Double? = nil, weight: Double? = nil, big: Int? = nil, created: Date? = nil, reference: UUID? = nil, picture: Data? = nil, key: UUID? = nil, pattern: BsonValue? = nil, patterns: [BsonValue]? = nil, text: String? = nil, parts: [Product.Part]? = nil, low: Int? = nil) {
        self.id = id
        self.sku = sku
        self.price = price
        self.stock = stock
        self.weight = weight
        self.big = big
        self.created = created
        self.reference = reference
        self.picture = picture
        self.key = key
        self.pattern = pattern
        self.patterns = patterns
        self.text = text
        self.parts = parts
        self.low = low
    }

    /// A nested document: it is stored with the one that holds it.
    public struct Part: Sendable, Equatable {
        public var name: String?
        public var inner: Product.Part.Inner?

        public init(name: String? = nil, inner: Product.Part.Inner? = nil) {
            self.name = name
            self.inner = inner
        }

        /// A nested document: it is stored with the one that holds it.
        public struct Inner: Sendable, Equatable {
            public var deep: BsonValue?

            public init(deep: BsonValue? = nil) {
                self.deep = deep
            }
        }
    }
}

extension Product: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Product {
        var entity = Product(
            id: try Bson.read(document, "_id", Bson.asObjectId),
            sku: try Bson.read(document, "sku", Bson.asText),
            price: try Bson.read(document, "price", Bson.asDecimal),
            stock: try Bson.read(document, "stock", Bson.asDouble),
            weight: try Bson.read(document, "weight", Bson.asDouble),
            big: try Bson.read(document, "big", Bson.asInt64),
            created: try Bson.read(document, "created", Bson.asDate),
            reference: try Bson.read(document, "reference", Bson.asUUID),
            picture: try Bson.read(document, "picture", Bson.asData),
            key: try Bson.read(document, "key", Bson.asUUID),
            pattern: try Bson.read(document, "pattern", Bson.asAny),
