/// Keeps audit-log rows in the database, through MongoKitten: on the database of the unit of work, or on its transaction.
public struct MongoAuditLogRepository: AuditLogRepository {
    let database: Db

    public init(db: Db) {
        self.database = db
    }

    public func findById(_ id: String) async throws -> AuditLog? {
        let documentFilter: BsonDocument = ["_id": try Bson.ofText(id)]
        return try await database.find("audit-log", documentFilter, limit: 1).first.map(AuditLog.from)
    }

    public func list(offset: Int, limit: Int) async throws -> Page<AuditLog> {
        let documentFilter: BsonDocument = [:]
        let total = try await database.count("audit-log", documentFilter)
        let found = limit > 0 ? try await database.find("audit-log", documentFilter, sort: ["_id": 1], skip: offset, limit: limit) : []
        return Page(items: try found.map(AuditLog.from), total: total, offset: offset, limit: limit)
    }

    @discardableResult
    public func insert(_ entity: AuditLog) async throws -> AuditLog {
        var entity = entity
        let document = try entity.toDocument()
        try await write { try await database.insert("audit-log", document) }
        entity.loadedDocument = Loaded(document: document)
        return entity
    }

    @discardableResult
    public func update(_ entity: AuditLog) async throws -> AuditLog {
        var entity = entity
        let now = try entity.toDocument()
        let fields = ["at", "by"]
        let changes = Bson.changes(entity.loadedDocument.document, now, fields)
        if !changes.isEmpty, let id = now["_id"] {
            try await write { try await database.update("audit-log", ["_id": id], changes) }
        }
        entity.loadedDocument = Loaded(document: now)
        return entity
    }

    public func delete(_ entity: AuditLog) async throws {
        let documentFilter: BsonDocument = ["_id": try Bson.ofText(entity.id!)]
        try await write { try await database.delete("audit-log", documentFilter) }
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "AuditLog", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

