import Foundation

/// Operations on audit-log. Repositories commit every write.
public struct AuditLogService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new AuditLog after checking it.
    @discardableResult
    public func createAuditLog(_ data: AuditLogCreate) async throws -> AuditLogRead {
        let values = Values(id: data.id.map(Optional.some), at: data.at.map(Optional.some), by: data.by.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = AuditLog()
            applyValues(&entity, values)
            return try await read(uow.auditLog.insert(entity))
        }
    }

    /// The AuditLog with this key; notFound when there is none.
    public func getAuditLog(_ id: String) async throws -> AuditLogRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of audit-log, by primary key.
    public func listAuditLogs(offset: Int, limit: Int) async throws -> Page<AuditLogRead> {
        try await unitOfWork.auditLog.list(offset: offset, limit: limit).map(read)
    }

    /// Changes the given values of a AuditLog.
    @discardableResult
    public func updateAuditLog(_ id: String, _ changes: AuditLogUpdate) async throws -> AuditLogRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.auditLog.update(current))
        }
    }

    /// Deletes a AuditLog.
    public func deleteAuditLog(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.auditLog.delete(current)
        }
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var id: String?? = nil
    var at: Date?? = nil
    var by: BsonValue?? = nil
}

/// Checks the values against the rules of the "audit-log" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: AuditLog?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if values.id ?? nil == nil && (creating || values.id != nil) {
        errors.append(FieldError("_id", "is required"))
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "AuditLog", errors: errors) }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: AuditLog?) async throws {
    try await validate(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout AuditLog, _ values: Values) {
    if let value = values.id { entity.id = value }
    if let value = values.at { entity.at = value }
    if let value = values.by { entity.by = value }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: AuditLogUpdate) -> Values {
    Values(at: changes.at.given, by: changes.by.given)
}

/// The AuditLog with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: String) async throws -> AuditLog {
    guard let row = try await uow.auditLog.findById(id) else {
        throw DomainError.notFound(entity: "AuditLog", key: "\(id)")
    }
    return row
}

/// The AuditLog as services return it.
fileprivate func read(_ entity: AuditLog) -> AuditLogRead {
    AuditLogRead(id: entity.id!, at: entity.at, by: entity.by)
}

