    }

    /// Stores a new Product after checking it.
    @discardableResult
    public func createProduct(_ data: ProductCreate) async throws -> ProductRead {
        let values = Values(sku: data.sku.map(Optional.some), price: data.price.map(Optional.some), stock: data.stock.map(Optional.some), weight: data.weight.map(Optional.some), big: data.big.map(Optional.some), created: data.created.map(Optional.some), reference: data.reference.map(Optional.some), picture: data.picture.map(Optional.some), key: data.key.map(Optional.some), pattern: data.pattern.map(Optional.some), patterns: data.patterns.map(Optional.some), text: data.text.map(Optional.some), parts: data.parts.map(Optional.some), low: data.low.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
