    }

    /// Changes the given values of a Product.
    @discardableResult
    public func updateProduct(_ id: String, _ changes: ProductUpdate) async throws -> ProductRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.products.update(current))
        }
    }

    /// Deletes a Product.
    public func deleteProduct(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.products.delete(current)
        }
    }

    /// Adds an item to patterns.
    @discardableResult
    public func addPattern(_ id: String, _ pattern: BsonValue) async throws -> ProductRead {
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.products.addPattern(id, pattern) else {
                throw DomainError.notFound(entity: "Product", key: "\(id)")
            }
            return read(changed)
        }
    }

    /// Removes an item from patterns, by its position.
    @discardableResult
    public func removePattern(_ id: String, _ position: Int) async throws -> ProductRead {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(current.patterns ?? []).indices.contains(position) {
                throw DomainError.notFound(entity: "Pattern", key: "\(position)")
            }
            guard let changed = try await uow.products.removePattern(id, position, (current.patterns ?? []).count) else {
                throw DomainError.conflict(entity: "Product", reason: "was changed by someone else since it was read", fields: ["patterns"])
            }
            return read(changed)
        }
    }

