    @discardableResult
    public func addPart(_ id: String, _ part: Product.Part) async throws -> ProductRead {
        var errors: [FieldError] = []
        checkProductPart(part, "parts", &errors)
        if !errors.isEmpty { throw DomainError.validationFailed(entity: "Product", errors: errors) }
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.products.addPart(id, part) else {
                throw DomainError.notFound(entity: "Product", key: "\(id)")
            }
            return read(changed)
        }
    }

    /// Removes an item from parts, by its position.
    @discardableResult
    public func removePart(_ id: String, _ position: Int) async throws -> ProductRead {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(current.parts ?? []).indices.contains(position) {
                throw DomainError.notFound(entity: "Part", key: "\(position)")
            }
            guard let changed = try await uow.products.removePart(id, position, (current.parts ?? []).count) else {
                throw DomainError.conflict(entity: "Product", reason: "was changed by someone else since it was read", fields: ["parts"])
            }
            return read(changed)
        }
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var sku: String?? = nil
    var price: Decimal?? = nil
    var stock: Double?? = nil
    var weight: Double?? = nil
    var big: Int?? = nil
    var created: Date?? = nil
    var reference: UUID?? = nil
    var picture: Data?? = nil
    var key: UUID?? = nil
    var pattern: BsonValue?? = nil
    var patterns: [BsonValue]?? = nil
    var text: String?? = nil
    var parts: [Product.Part]?? = nil
    var low: Int?? = nil
}

/// Checks the values against the rules of the "products" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Product?) async throws {
    var errors: [FieldError] = []
    if let value = values.parts ?? nil {
        for (i0, item0) in value.enumerated() {
            checkProductPart(item0, "parts.\(i0)", &errors)
        }
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Product", errors: errors) }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Product?) async throws {
    try await validate(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Product, _ values: Values) {
    if let value = values.sku { entity.sku = value }
    if let value = values.price { entity.price = value }
    if let value = values.stock { entity.stock = value }
    if let value = values.weight { entity.weight = value }
    if let value = values.big { entity.big = value }
    if let value = values.created { entity.created = value }
    if let value = values.reference { entity.reference = value }
    if let value = values.picture { entity.picture = value }
    if let value = values.key { entity.key = value }
    if let value = values.pattern { entity.pattern = value }
    if let value = values.patterns { entity.patterns = value }
    if let value = values.text { entity.text = value }
    if let value = values.parts { entity.parts = value }
    if let value = values.low { entity.low = value }
}

/// What a Product.Part does not follow of its rules, each with the path of its field.
fileprivate func checkProductPart(_ value: Product.Part, _ path: String, _ errors: inout [FieldError]) {
    if let held = value.inner {
        checkProductPartInner(held, "\(path).inner", &errors)
    }
}

/// What a Product.Part.Inner does not follow of its rules, each with the path of its field.
fileprivate func checkProductPartInner(_ value: Product.Part.Inner, _ path: String, _ errors: inout [FieldError]) {
}

/// The values an update gives, by field.
fileprivate func given(_ changes: ProductUpdate) -> Values {
    Values(sku: changes.sku.given, price: changes.price.given, stock: changes.stock.given, weight: changes.weight.given, big: changes.big.given, created: changes.created.given, reference: changes.reference.given, picture: changes.picture.given, key: changes.key.given, pattern: changes.pattern.given, patterns: changes.patterns.given, text: changes.text.given, parts: changes.parts.given, low: changes.low.given)
}

/// The Product with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: String) async throws -> Product {
    guard let row = try await uow.products.findById(id) else {
        throw DomainError.notFound(entity: "Product", key: "\(id)")
    }
    return row
