/// The Product as services return it.
fileprivate func read(_ entity: Product) -> ProductRead {
    ProductRead(id: entity.id!, sku: entity.sku, price: entity.price, stock: entity.stock, weight: entity.weight, big: entity.big, created: entity.created, reference: entity.reference, picture: entity.picture, key: entity.key, pattern: entity.pattern, patterns: entity.patterns, text: entity.text, parts: entity.parts, low: entity.low)
