    static func newProduct(_ n: Int) -> Product {
        Product(sku: "sku-\(n)", price: Decimal(string: "\(n % 10000).50")!, stock: Double(n) + 0.5, weight: Double(n) + 0.5, big: n, created: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)), reference: UUID(uuidString: String(format: "00000000-0000-4000-8000-%012d", n))!, picture: Data([UInt8(n % 256)]), key: UUID(uuidString: String(format: "00000000-0000-4000-8000-%012d", n))!, pattern: BsonValue(["n": n] as BsonDocument), patterns: [], text: "text-\(n)", parts: [newProductPart(n)], low: n)
    }

