import Foundation
import MongoKitten
import Testing
@testable import MongoswiftMongodbFromMongosh

/// Every test is in this suite, one after another: they all empty the same database.
@Suite(.serialized) struct DataTests {}

/// The test database: the MongoDB database TEST_DATABASE_URL names, created again before every test.
enum TestDatabase {
    /// Runs body with the repositories over the test database, with every table dropped and created again first.
    static func with(_ body: (MongoUnitOfWork) async throws -> Void) async throws {
        let url = try #require(
            ProcessInfo.processInfo.environment["TEST_DATABASE_URL"],
            "The database tests need a disposable MongoDB database (a replica set, for its transactions): set TEST_DATABASE_URL (it is emptied)")
        let app = try await AppDatabase(url: url)
        do {
            try await recreate(app.database)
            try await body(MongoUnitOfWork(db: app.database))
        } catch {
            await app.shutdown()
            throw error
        }
        await app.shutdown()
    }

    /// Drops the database and creates its collections and their indexes again.
    private static func recreate(_ db: Db) async throws {
        try await db.run(["dropDatabase": 1])
        try await db.run(["create": "products"])
        try await db.run(["create": "audit-log"])
    }
}

/// The DomainError work throws, or nil when it throws none.
func refusal<T>(_ work: () async throws -> T) async -> DomainError? {
    do {
        _ = try await work()
        return nil
    } catch let error as DomainError {
        return error
    } catch {
        return nil
    }
}

func isConflict(_ error: DomainError?) -> Bool {
    if case .some(.conflict) = error { true } else { false }
}

func isNotFound(_ error: DomainError?) -> Bool {
    if case .some(.notFound) = error { true } else { false }
}

